import csv,json,struct,hashlib
from pathlib import Path
from unicorn import *
from unicorn.x86_const import *
R=Path(__file__).resolve().parents[1];b=(R/'baseline48/prior/inputs/nite3w - 110.exe').read_bytes();assert hashlib.sha256(b).hexdigest()=='12fe5168783446275802e0e947898261b5eca6b88288f3a895fc1faa4c544481';c=b[0xe8a0:0xe8a0+0x73fe]
u=Uc(UC_ARCH_X86,UC_MODE_16);u.mem_map(0,0x100000);u.mem_write(0x20000,c);D=0x10480;S=0x40000;end={}
def hook(u,a,n,data):
 if a in [0x2f000,0x23c3d,0x3e000]:end.update(address=a);u.emu_stop()
u.hook_add(UC_HOOK_CODE,hook);counts={'return':0,'fatal':0,'alternate':0};samples=[]
def run(req,base,floor,water,alternate=False):
 end.clear();rounded=(req+1)&65534;new=base-rounded;success=rounded<base and new>=floor
 for reg,v in [(UC_X86_REG_CS,0x2000),(UC_X86_REG_DS,0x1048),(UC_X86_REG_SS,0x4000),(UC_X86_REG_SP,base-4),(UC_X86_REG_BP,0x1234),(UC_X86_REG_AX,req),(UC_X86_REG_EFLAGS,2)]:u.reg_write(reg,v)
 u.mem_write(S+base-4,struct.pack('<2H',0xf000,0x2000));u.mem_write(S+10,struct.pack('<2H',floor,water));u.mem_write(D+10,b'\xa5'*4);u.mem_write(D+0x8b0,struct.pack('<2H',0xe000 if alternate else 65535,0x3000))
 u.emu_start(0x239f2,0x2f001,count=100)
 assert end['address']==(0x2f000 if success else (0x3e000 if alternate else 0x23c3d))
 assert u.reg_read(UC_X86_REG_SP)==(new if success else base)
 assert u.reg_read(UC_X86_REG_BP)==0x1234 and u.reg_read(UC_X86_REG_DS)==0x1048
 assert bytes(u.mem_read(D+10,4))==b'\xa5'*4
 assert struct.unpack('<H',u.mem_read(S+12,2))[0]==(min(water,new) if success else water)
 if success:assert u.reg_read(UC_X86_REG_AX)==new
 elif not alternate:assert u.reg_read(UC_X86_REG_AX)==0
 counts['return' if success else ('alternate' if alternate else 'fatal')]+=1
 if req in [0,1,65534,65535] and base==0xd000 and floor==0x1000 and water==65535:samples.append(dict(request=req,rounded=rounded,success=success,result_sp=u.reg_read(UC_X86_REG_SP)))
for req in range(65536):run(req,0xd000,0x1000,65535)
extra=0
for base in [0x2000,0x8000,0xd000,0xfff0]:
 for req in [0,1,2,3,16,0x100,0x1000,65534,65535]:
  new=base-((req+1)&65534)
  for floor in [0x1000,base,max(0x1000,min(65535,new+1))]:
   for water in [0x800,base,65535]:
    for alternate in [False,True]:run(req,base,floor,water,alternate);extra+=1
rows=[r for r in csv.DictReader(open(R/'baseline48/pass48-results/listing.tsv'),delimiter='\t') if r['address'].startswith('1008:') and 0x39f2<=int(r['address'][5:],16)<0x3a25]
for r in rows:
 a=int(r['address'][5:],16);assert c[a:a+len(r['bytes'])//2].hex()==r['bytes']
out=dict(cases=65536+extra,exhaustive_requests=65536,boundary_cases=extra,counts=counts,samples=samples,rounded='wrap16(request+1)&FFFE',success='rounded<post-popSP and post-popSP-rounded>=SS[000A]',low_water='SS000C=min(previous,newSP) on success',DS_SS_distinct=True,stubs=[],full_game_runtime=False,limits=['Alternate handler stops at entry,body not executed','Fatal stops before3C3D body','Synthetic far-return frame;not actual Win16 stack growth'])
(R/'pass60/verification.json').write_text(json.dumps(out,indent=2)+'\n');(R/'pass60/native_listing.json').write_text(json.dumps(rows,indent=2));print(json.dumps(out))

